const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;padding:12px;display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font:13px/1.45 system-ui,-apple-system,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:8px}\n.home,.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.pane{gap:8px}\n\n/* buttons */\n.btn{flex:1;min-width:0;height:32px;padding:0 8px;border-radius:10px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font:inherit;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn.primary{background:var(--accent);border-color:transparent;color:var(--on-accent)}\n.ib{flex:none;width:28px;height:32px;padding:0;border-radius:8px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font:inherit;font-size:16px;line-height:1;cursor:pointer;display:grid;place-items:center}\n.card[data-size=\"3x3\"] .ib{width:26px}\n.btn:disabled,.ib:disabled{opacity:.4;cursor:default}\n.btn:focus-visible,.ib:focus-visible,.ta:focus-visible,.row:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n/* home */\n.main{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.main.clickable{cursor:pointer}\n.hd{flex:none;min-width:0}\n.eyebrow{font-size:11px;font-weight:700;letter-spacing:.1em;color:var(--accent)}\n.src{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.focus{list-style:none;margin:0;padding:0;flex:1 1 0;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin}\n.fi{flex:none;display:flex;gap:8px;align-items:flex-start;background:var(--soft);border-radius:10px;padding:6px 8px}\n.fn{flex:none;width:18px;height:18px;margin-top:1px;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:700;display:grid;place-items:center}\n.ft{min-width:0;overflow-wrap:anywhere;font-size:13px;line-height:1.45}\n.empty{flex:1 1 0;min-height:0;overflow:auto;display:flex;flex-direction:column;justify-content:center;gap:4px}\n.empty-t{font-size:14px;font-weight:700}\n.empty-d{font-size:12px;color:var(--muted)}\n.recap{display:none}\n.acts{flex:none;display:flex;gap:6px}\n\n/* pane header / footer */\n.ph{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.vt{flex:1;min-width:0;text-align:center}\n.vt-a{font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.vt-b{font-size:11px;color:var(--muted);min-height:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pf{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n.note{flex:0 0 100%;font-size:11px;color:var(--ink);line-height:1.35}\n.pb{flex:1;min-height:0;min-width:0}\n\n\n/* edit */\n.flds{display:flex;flex-direction:column;gap:8px;overflow:auto;scrollbar-width:thin}\n.fld{flex:1 0 76px;display:flex;flex-direction:column;gap:3px;min-height:0;min-width:0}\n.fl{flex:none;font-size:12px;font-weight:700}\n.ta{display:block;width:100%;flex:1;min-height:56px;resize:none;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px;line-height:1.45;padding:6px 8px}\n.ta::placeholder{color:var(--muted)}\n\n/* detail */\n.secs{display:flex;flex-direction:column;gap:10px;overflow:auto;scrollbar-width:thin}\n.sec{flex:none;min-width:0;border-left:3px solid var(--line);padding-left:8px}\n.sec.adj{border-left-color:var(--accent)}\n.sh{margin:0 0 2px;font-size:12px;font-weight:700;color:var(--accent)}\n.sb{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.5}\n.sb.none{color:var(--muted)}\n\n/* history */\n.list{display:flex;flex-direction:column;gap:6px;overflow:auto;scrollbar-width:thin}\n.row{flex:none;display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--soft);color:var(--ink);font:inherit;cursor:pointer}\n.row-m{flex:1;min-width:0}\n.row-w{font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row-p{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row-c{flex:none;color:var(--muted);font-size:16px}\n\n/* 6x3: wide and short */\n.card[data-size=\"6x3\"] .home{flex-direction:row;gap:12px}\n.card[data-size=\"6x3\"] .acts{flex-direction:column;justify-content:flex-end;width:116px}\n.card[data-size=\"6x3\"] .acts .btn{flex:none}\n.card[data-size=\"6x3\"] .pane{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr);gap:8px}\n.card[data-size=\"6x3\"] .pane>.ph{grid-column:1;grid-row:1}\n.card[data-size=\"6x3\"] .pane.nof>.ph{grid-column:1/3}\n.card[data-size=\"6x3\"] .pane>.pf{grid-column:2;grid-row:1;flex-wrap:wrap;justify-content:flex-end;max-width:210px}\n.card[data-size=\"6x3\"] .pane>.pb{grid-column:1/3;grid-row:2}\n.card[data-size=\"6x3\"] .pf .btn{flex:none;padding:0 14px}\n.card[data-size=\"6x3\"] .flds,.card[data-size=\"6x3\"] .secs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:minmax(0,1fr);gap:8px;overflow:visible}\n.card[data-size=\"6x3\"] .fld{flex:none;min-height:0}\n.card[data-size=\"6x3\"] .ta{min-height:0}\n.card[data-size=\"6x3\"] .sec{overflow:auto;min-height:0;scrollbar-width:thin}\n.card[data-size=\"6x3\"] .vt-a{font-size:13px}\n\n/* tall and large: show last week's recap on home */\n.card[data-size=\"3x6\"] .recap,.card[data-size=\"6x6\"] .recap{flex:none;display:flex;flex-direction:column;gap:6px}\n.card[data-size=\"6x6\"] .recap{flex-direction:row;gap:12px}\n.rc{min-width:0;flex:1;border-left:3px solid var(--line);padding-left:8px}\n.rc-l{font-size:11px;font-weight:700;color:var(--muted)}\n.rc-t{font-size:12px;overflow-wrap:anywhere;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}\n.card[data-size=\"6x6\"] .rc-t{-webkit-line-clamp:4;font-size:13px}\n.rc-t.none{color:var(--muted)}\n.card[data-size=\"6x6\"] .eyebrow{font-size:12px}\n.card[data-size=\"6x6\"] .ft{font-size:14px}\n.card[data-size=\"6x6\"],.card[data-size=\"3x6\"]{padding:14px}\n.card[data-size=\"3x6\"] .row-p,.card[data-size=\"6x6\"] .row-p{white-space:normal;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}\n.card[data-size=\"6x6\"] .btn,.card[data-size=\"3x6\"] .btn{font-size:13px}\n.card[data-size=\"6x6\"] .vt-a{font-size:14px}\n";
function pad2(n){return n<10?'0'+n:''+n}
function parseDay(s){var p=String(s).split('-').map(Number);return new Date(p[0],p[1]-1,p[2])}
function fmtDay(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())}
function weekStartOf(s){var d=parseDay(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return fmtDay(d)}
function addWeeks(ws,n){var d=parseDay(ws);d.setDate(d.getDate()+7*n);return fmtDay(d)}
function weekLabel(ws){
  var a=parseDay(ws),b=parseDay(ws);b.setDate(b.getDate()+6);
  var s=(a.getMonth()+1)+'月'+a.getDate()+'日–';
  if(a.getMonth()!==b.getMonth())s+=(b.getMonth()+1)+'月';
  return s+b.getDate()+'日';
}
function lines(t){return String(t||'').split('\n').map(function(x){return x.trim().replace(/^[-•·*]\s*/,'')}).filter(Boolean)}
function oneLine(t){return String(t||'').replace(/\s+/g,' ').trim()}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const today=day(),curWs=weekStartOf(today),curYear=parseDay(today).getFullYear();
  const srcList=state&&Array.isArray(state.reviews)?state.reviews:[];
  const reviews=srcList.filter(r=>r&&r.id&&typeof r.weekStart==='string').slice().sort((a,b)=>a.weekStart<b.weekStart?1:(a.weekStart>b.weekStart?-1:0));
  const byWeek=ws=>reviews.find(r=>r.weekStart===ws);
  const box=(tag,cls,...kids)=>el(tag,{class:cls},...kids.filter(k=>k!=null&&k!==false&&k!==''));
  const btn=(label,onclick,cls,extra)=>el('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick:onclick},extra||{}),label);
  const ib=(label,aria,onclick,disabled)=>{
    const a={type:'button',class:'ib','aria-label':aria,onclick:onclick};
    if(disabled)a.disabled=true;
    return el('button',a,label);
  };
  const go=patch=>{Object.assign(ui,patch);redraw()};
  const yearTag=ws=>{const y=parseDay(ws).getFullYear();return y!==curYear?y+'年':''};

  function openEdit(ws,back){
    go({view:'edit',editWeek:ws,back:back,err:'',saving:false,confirmDel:false});
  }

  function recapBlock(label,text){
    const t=String(text||'').trim();
    return box('div','rc',box('div','rc-l',label),box('div','rc-t'+(t?'':' none'),t||'未填写'));
  }

  function renderHome(){
    const latest=reviews[0],cur=byWeek(curWs);
    const items=latest?lines(latest.adjust):[];
    const hd=box('div','hd',
      box('div','eyebrow','下周重点'),
      latest&&box('div','src','来自 '+[yearTag(latest.weekStart),weekLabel(latest.weekStart)].filter(Boolean).join(' ')+' 的复盘'));
    let body;
    if(!latest){
      body=box('div','empty',box('div','empty-t','还没有复盘'),box('div','empty-d','每周写下进步、困难和下周要调整的事，最新一周的调整会显示在这里。'));
    }else if(!items.length){
      body=box('div','empty',box('div','empty-t','这周没写下周调整'),box('div','empty-d','补上「下周要调整的事」，就会显示在这里。'));
    }else{
      body=box('ul','focus',...items.map((t,i)=>box('li','fi',box('span','fn',String(i+1)),box('span','ft',t))));
    }
    const hasRecap=latest&&(String(latest.progress||'').trim()||String(latest.difficulty||'').trim());
    const recap=hasRecap&&box('div','recap',recapBlock('进步',latest.progress),recapBlock('困难',latest.difficulty));
    const mainAttrs={class:'main'+(reviews.length?' clickable':'')};
    if(reviews.length)mainAttrs.onclick=()=>go({view:'history'});
    const main=el('div',mainAttrs,...[hd,body,recap].filter(Boolean));
    const acts=box('div','acts',
      btn(cur?'改本周复盘':'写本周复盘',()=>openEdit(curWs,'home'),'primary'),
      reviews.length>0&&btn('历史 · '+reviews.length,()=>go({view:'history'}),'ghost'));
    return box('div','home',main,acts);
  }


  function renderHistory(){
    const rows=reviews.map(r=>{
      const p=oneLine(r.progress),q=oneLine(r.difficulty),a=oneLine(r.adjust);
      const pv=p?'进步 '+p:(q?'困难 '+q:(a?'调整 '+a:'（内容为空）'));
      const title=[yearTag(r.weekStart),weekLabel(r.weekStart)].filter(Boolean).join(' ')+(r.weekStart===curWs?' · 本周':'');
      return el('button',{type:'button',class:'row',onclick:()=>go({view:'detail',openWs:r.weekStart,confirmDel:false,derr:''})},
        box('div','row-m',box('div','row-w',title),box('div','row-p',pv)),
        box('span','row-c','›'));
    });
    const hd=box('div','ph',
      ib('←','返回',()=>go({view:'home'})),
      box('div','vt',box('div','vt-a','历史记录'),box('div','vt-b','共 '+reviews.length+' 周')),
      ib('+','写本周复盘或补写其他周',()=>openEdit(curWs,'history')));
    return box('div','pane nof',hd,box('div','pb list',...rows));
  }

  function sec(title,text,extra){
    const t=String(text||'').trim();
    return box('section','sec'+(extra?' '+extra:''),box('h3','sh',title),box('div','sb'+(t?'':' none'),t||'未填写'));
  }

  function del(ws){
    commit(
      s=>Object.assign({},s,{reviews:(s&&Array.isArray(s.reviews)?s.reviews:[]).filter(r=>r.weekStart!==ws)}),
      Object.assign({},ui,{view:'history',openWs:null,confirmDel:false,derr:''})
    ).catch(()=>{ui.derr='删除失败，请重试';ui.confirmDel=false;redraw()});
  }

  function renderDetail(){
    const r=byWeek(ui.openWs),i=reviews.indexOf(r);
    const older=reviews[i+1],newer=i>0?reviews[i-1]:null;
    const nav=w=>{if(w)go({openWs:w.weekStart,confirmDel:false,derr:''})};
    const sub=[yearTag(r.weekStart),r.weekStart===curWs?'本周':''].filter(Boolean).join(' · ');
    const hd=box('div','ph',
      ib('←','返回历史',()=>go({view:'history',confirmDel:false})),
      box('div','vt',box('div','vt-a',weekLabel(r.weekStart)),box('div','vt-b',sub)));
    const secs=box('div','pb secs',sec('进步',r.progress),sec('遇到的困难',r.difficulty),sec('下周要调整的事',r.adjust,'adj'));
    let ft;
    if(ui.confirmDel){
      ft=box('div','pf',
        box('div','note','确认删除这周的复盘？删除后无法恢复。'),
        btn('取消',()=>go({confirmDel:false}),'ghost'),
        btn('确认删除',()=>del(r.weekStart),'primary'));
    }else{
      ft=box('div','pf',
        ui.derr&&box('div','note','⚠ '+ui.derr),
        ib('‹','更早一周',()=>nav(older),!older),
        btn('修改',()=>openEdit(r.weekStart,'detail'),'primary'),
        btn('删除',()=>go({confirmDel:true,derr:''}),'ghost'),
        ib('›','更晚一周',()=>nav(newer),!newer));
    }
    return box('div','pane',hd,secs,ft);
  }


  function getDraft(ws){
    ui.drafts=ui.drafts||{};
    if(!ui.drafts[ws]){
      const r=byWeek(ws);
      ui.drafts[ws]={progress:r?(r.progress||''):'',difficulty:r?(r.difficulty||''):'',adjust:r?(r.adjust||''):''};
    }
    return ui.drafts[ws];
  }

  function leaveEdit(){
    const nd=Object.assign({},ui.drafts);
    delete nd[ui.editWeek||curWs];
    const b=ui.back;
    go({drafts:nd,err:'',saving:false,view:b==='detail'?'detail':(b==='history'?'history':'home')});
  }

  function save(){
    if(ui.saving)return;
    const ws=ui.editWeek||curWs,d=getDraft(ws);
    const v={progress:d.progress.trim(),difficulty:d.difficulty.trim(),adjust:d.adjust.trim()};
    if(!v.progress&&!v.difficulty&&!v.adjust){ui.err='至少填写一项再保存';redraw();return}
    const newId=uid(),now=Date.now();
    const nd=Object.assign({},ui.drafts);
    delete nd[ws];
    const next=Object.assign({},ui,{drafts:nd,saving:false,err:'',view:ui.back==='home'?'home':'detail',openWs:ws});
    ui.saving=true;ui.err='';
    redraw();
    commit(s=>{
      const list=s&&Array.isArray(s.reviews)?s.reviews.slice():[];
      const i=list.findIndex(r=>r&&r.weekStart===ws);
      const rec=Object.assign({},i>=0?list[i]:{id:newId,weekStart:ws,createdAt:now},v,{updatedAt:now});
      if(i>=0)list[i]=rec;else list.push(rec);
      return Object.assign({},s,{reviews:list});
    },next).catch(()=>{ui.saving=false;ui.err='保存失败，请重试（已填内容还在）';redraw()});
  }

  function renderEdit(){
    const ws=ui.editWeek||curWs,d=getDraft(ws),exist=byWeek(ws);
    const shift=n=>{const nw=addWeeks(ws,n);if(nw>curWs)return;go({editWeek:nw,err:''})};
    const sub=[yearTag(ws),ws===curWs?'本周':'补写',exist?'已有记录':''].filter(Boolean).join(' · ');
    const hd=box('div','ph',
      ib('‹','上一周',()=>shift(-1)),
      box('div','vt',box('div','vt-a',weekLabel(ws)),box('div','vt-b',sub)),
      ib('›','下一周',()=>shift(1),ws>=curWs));
    const fld=(key,label,ph)=>{
      const ta=el('textarea',{class:'ta',placeholder:ph,'aria-label':label,oninput:e=>{d[key]=e.target.value}});
      ta.value=d[key];
      return box('label','fld',box('span','fl',label),ta);
    };
    const flds=box('div','pb flds',
      fld('progress','这周的进步','做成了什么、哪里比上周更好'),
      fld('difficulty','遇到的困难','卡在哪里、什么拖慢了你'),
      fld('adjust','下周要调整的事','一行一条，会显示在卡片首页'));
    const ft=box('div','pf',
      ui.err&&box('div','note','⚠ '+ui.err),
      btn('取消',leaveEdit,'ghost'),
      btn(ui.saving?'保存中…':'保存',save,'primary',ui.saving?{disabled:true}:null));
    return box('div','pane',hd,flds,ft);
  }

  function render(){
    let v=ui.view||'home';
    if(v==='detail'&&!byWeek(ui.openWs))v='history';
    if(v==='history'&&!reviews.length)v='home';
    root.append(v==='edit'?renderEdit():(v==='detail'?renderDetail():(v==='history'?renderHistory():renderHome())));
  }
  render();
}

const RUNTIME_BUILD='v50-r22-theme-20261102';
const INFRA_CSS=`:host{display:block;width:100%;height:100%}*{box-sizing:border-box}.card{width:100%;height:100%;position:relative;container:card / size;min-width:0;min-height:0;overflow:auto}button,input,textarea,select{font:inherit}button{cursor:pointer;touch-action:manipulation}.infra-panel{position:absolute;inset:0;z-index:100;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:10px;padding:12px;background:var(--panel-paper);color:var(--ink);overflow:hidden;font:13px/1.4 system-ui}.infra-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.infra-content{overflow:auto;min-height:0}.infra-actions{display:flex;gap:6px;flex-wrap:wrap}.infra-panel button{border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:var(--button-paper);color:inherit}.infra-panel button[data-primary]{background:var(--accent);color:var(--on-accent)}.infra-form{display:grid;gap:10px}.infra-form label{display:grid;gap:4px}.infra-form input:not([type=checkbox]),.infra-form textarea,.infra-form select{width:100%;min-width:0;padding:8px;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:inherit}.infra-error{color:var(--danger);font-size:12px}.infra-form textarea{min-height:65px}`;
export default class Card extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.state={};this.ui={};this.queue=Promise.resolve();this.epoch=0;this.pending=0;}
 set tabbitHost(h){this.host=h;if(this.isConnected)this.load();}
 connectedCallback(){if(this.host)this.load();}
 disconnectedCallback(){this.epoch++;this.stop();}
 destroy(){this.disconnectedCallback();}
 stop(){this.cleanup?.();this.cleanup=null;clearInterval(this.dateTimer);this.dateTimer=null;}
 day(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
 async load(){const e=++this.epoch;this.stop();try{const r=await this.host.storage.get('state');if(e!==this.epoch||!this.isConnected)return;this.state=r.entry?.value||{};if(typeof initialize==='function'){const original=JSON.stringify(this.state);const prepared=initialize(JSON.parse(original));if(!prepared||typeof prepared!=='object')throw Error('initialize must return state');if(JSON.stringify(prepared)!==original){await this.host.storage.set('state',prepared);if(e!==this.epoch||!this.isConnected)return;this.state=prepared;}}this.ui={};this.saveError='';this.render();this.lastDay=this.day();this.dateTimer=setInterval(()=>{if(this.day()!==this.lastDay&&!this.pending){this.lastDay=this.day();this.render();}},1000);}catch(error){if(e===this.epoch)this.showError(error);}}
 contextShape(){const c=this.host.ctx;return JSON.stringify(Object.fromEntries(Object.entries(c).filter(([k])=>k!=='colors')));}
